lemma hubbleConstant_ne_zero {a : Time → ℝ} {t : Time}
    (hd_az : ∂ₜ a t ≠ 0) (haz : a t ≠ 0) :
    hubbleConstant a t ≠ 0

lemma _root_.Cosmology.FLRW.friedmannSolution_iff_addCosmologicalConstant {U : FLRW}
    {F : CosmicFluid} {Λ G : ℝ} {c : SpeedOfLight} (hG : G ≠ 0) :
    U.FriedmannSolution F Λ G c ↔ U.FriedmannSolution (F.addCosmologicalConstant Λ G c) 0 G c

lemma _root_.Cosmology.FLRW.FriedmannSolution.continuityEquation {U : FLRW} {F : CosmicFluid}
    {Λ G : ℝ} {c : SpeedOfLight} (h : U.FriedmannSolution F Λ G c) (hG : G ≠ 0) {t : Time}
    (ht : t ∈ U.I) (hdρ : DifferentiableAt ℝ F.ρ t) :
    ContinuityEquation U.a F.ρ F.p c t

lemma deriv_of_continuityEquation_barotropic {a ρ : Time → ℝ} {w : ℝ} {c : SpeedOfLight}
    {t : Time} (hC : ContinuityEquation a ρ (barotropicPressure w ρ c) c t) :
    ∂ₜ ρ t = -3 * (1 + w) * hubbleConstant a t * ρ t

lemma hubbleConstant_powerLaw {t₀ : Time} (ht₀ : 0 < t₀.val) (n : ℝ) {t : Time}
    (ht : 0 < t.val) :
    hubbleConstant (fun s : Time => (s.val / t₀.val) ^ n) t = n / t.val

lemma powerLaw_secondOrderFriedmann {t₀ : Time} {G : ℝ} {c : SpeedOfLight} {n w : ℝ}
    (ht₀ : 0 < t₀.val) (hG : 0 < G) (hn : n ≠ 0) (hw : 1 + 3 * w = 2 * (1 - n) / n) {t : Time}
    (ht : 0 < t.val) :
    SecondOrderFriedmann (fun s : Time => (s.val / t₀.val) ^ n)
      (fun s => 3 * n ^ 2 / (8 * π * G * s.val ^ 2))
      (fun s => w * (3 * n ^ 2 / (8 * π * G * s.val ^ 2)) * (c : ℝ) ^ 2) 0 G c t

lemma decelerationParameter_radiationScaleFactor {t₀ : Time} (ht₀ : 0 < t₀.val) {t : Time}
    (ht : 0 < t.val) :
    decelerationParameter (radiationScaleFactor t₀) t = 1

lemma einsteinStatic_density {a ρ : Time → ℝ} {Λ G : ℝ} {c : SpeedOfLight} {t : Time}
    (hG : 0 < G) (h2 : ∂ₜ (∂ₜ a) t = 0) (hF2 : SecondOrderFriedmann a ρ (fun _ => 0) Λ G c t) :
    ρ t = Λ * (c : ℝ) ^ 2 / (4 * π * G)
